// 2. Compute the inclusive prefix sums of the vector.
// 3. Convert the resulting vector back into a JSON array.
// 4. Return the JSON array.

use serde_json::Value;

pub fn solve(input: Value) -> Value {
    // Step 1: Parse the input JSON array into a vector of i64
    let numbers: Vec<i64> = match input {
        Value::Array(arr) => arr.into_iter().filter_map(|v| v.as_i64()).collect(),
        _ => Vec::new(),
    };

    // Step 2: Compute the inclusive prefix sums
    let prefix_sums: Vec<i64> = numbers
        .iter()
        .fold(vec![0], |mut acc, &x| {
            acc.push(acc.last().unwrap() + x);
            acc
        })
        .into_iter()
        .skip(1)
        .collect();

    // Step 3: Convert the resulting vector back into a JSON array
    Value::Array(prefix_sums.into_iter().map(Value::from).collect())
}

// Note: This implementation assumes that the input is always a valid JSON array of integers.
// If the input can be invalid, additional error handling should be added.
